body.script:
var SITE = {
  phoneDisplay: "07808 341760",
  phoneIntl: "+447808341760",
  whatsapp: "447808341760",
  instagram: "welcomehomecleaningc0",
  facebookUrl: "",
  email: ""
};

document.querySelectorAll("[data-phone-link]").forEach(function (a) {
  a.setAttribute("href", "tel:" + SITE.phoneIntl);
});
document.querySelectorAll("[data-phone-text]").forEach(function (t) {
  t.textContent = SITE.phoneDisplay;
});
document.querySelectorAll("[data-wa-link]").forEach(function (a) {
  a.setAttribute("href", "https://wa.me/" + SITE.whatsapp);
  a.setAttribute("target", "_blank");
  a.setAttribute("rel", "noopener");
});
document.querySelectorAll("[data-instagram-link]").forEach(function (a) {
  a.setAttribute("href", "https://www.instagram.com/" + SITE.instagram + "/");
});
if (SITE.facebookUrl) {
  document.querySelectorAll("[data-facebook-link]").forEach(function (a) {
    a.setAttribute("href", SITE.facebookUrl);
  });
  document.querySelectorAll("[data-facebook-row]").forEach(function (r) { r.hidden = false; });
}
if (SITE.email) {
  document.querySelectorAll("[data-email-link]").forEach(function (a) {
    a.setAttribute("href", "mailto:" + SITE.email);
    a.textContent = SITE.email;
  });
  document.querySelectorAll("[data-email-row]").forEach(function (r) { r.hidden = false; });
  document.getElementById("send-email").hidden = false;
}

document.getElementById("year").textContent = new Date().getFullYear();

document.querySelectorAll("[data-service]").forEach(function (link) {
  link.addEventListener("click", function () {
    document.getElementById("q-service").value = link.getAttribute("data-service");
  });
});

var form = document.getElementById("quote-form");
var status = document.getElementById("form-status");

function buildMessage() {
  var f = form;
  var name = f.name.value.trim();
  var phone = f.phone.value.trim();
  var postcode = f.postcode.value.trim();
  var service = f.service.value;
  if (!name || !phone || !postcode || !service) {
    status.textContent = "Please fill in your name, phone number, postcode and service.";
    status.style.color = "#b3261e";
    return null;
  }
  status.style.color = "";
  return {
    service: service,
    text:
      "Hi, I'd like a quote.\n" +
      "Name: " + name + "\n" +
      "Phone: " + phone + "\n" +
      "Postcode: " + postcode + "\n" +
      "Service: " + service + "\n" +
      "Bedrooms: " + f.bedrooms.value + "\n" +
      "Bathrooms: " + f.bathrooms.value + "\n" +
      "Notes: " + (f.message.value.trim() || "-")
  };
}

form.addEventListener("submit", function (e) {
  e.preventDefault();
  var m = buildMessage();
  if (!m) return;
  status.textContent = "Opening WhatsApp… just press send.";
  window.location.href = "https://wa.me/" + SITE.whatsapp + "?text=" + encodeURIComponent(m.text);
});

document.getElementById("send-email").addEventListener("click", function () {
  var m = buildMessage();
  if (!m) return;
  status.textContent = "Opening your email app… just press send.";
  window.location.href =
    "mailto:" + SITE.email +
    "?subject=" + encodeURIComponent("Quote request: " + m.service) +
    "&body=" + encodeURIComponent(m.text);
});
